SELECT id, name, email, country, segment, signup_date, is_active, credit_limit, age, NTILE(3) OVER (PARTITION BY city ORDER BY age, id) AS age_bucket, SUM(age) OVER (PARTITION BY country ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_age, LAG(age, 2, 0) OVER w_running AS prev_age, NTILE(5) OVER w_ordered AS age_bucket_2 FROM customers WINDOW w_running AS (PARTITION BY city, country ORDER BY credit_limit, id), w_ordered AS (PARTITION BY segment, country ORDER BY age DESC, id)
